from src.typers import *
import os
import pickle
import zlib
from glob import glob
import zipfile
import numpy as np


def discounted_cumulative_sums(rewards, discount):
    rewards = rewards[::-1]
    x = rewards[0]
    a = [x]
    for r in rewards[1:]:
        x = discount * x + r
        a.append(x)

    return a[::-1]


class MemoryReplayBuffer:
    """A replay buffer to hold the experience generated by the selfplay."""

    def __init__(self, config: Config):
        self.config = config
        self.data = []
        self.new_samples = 0

    def __len__(self):
        return len(self.data)

    def reset(self):
        self.data = []
        self.new_samples = 0

    def finish_trajectory(self, seq: Trajectory, winner: int, last_reward: float):
        rewards = [s.reward for s in seq] + [last_reward]

        discount = self.config.getfloat('train', 'discount')
        value = discounted_cumulative_sums(rewards, discount)[1:]
        value = np.array(value, 'float32')
        value = np.sign(value) * np.abs(value) / (np.max(np.abs(value)) + 1e-10)

        # reassign rewards
        for i, (s, r) in enumerate(zip(seq, value)):
            if s.player != winner:
                r = -r
            seq[i] = s._replace(reward=r.item())

            # unused in training
            seq[i].state_observation.action = None

        return seq

    def save(self, seq: Trajectory, winner: int, last_reward: float):
        seq = self.finish_trajectory(seq, winner, last_reward)

        size = self.config.getint('train', 'num_trajectories_in_buffer')
        if len(self.data) > size:
            self.data.pop(0)

        self.data.append(seq)
        self.new_samples += len(seq)

    def sample_trajectory(self) -> Trajectory:
        """Samples a trajectory uniformly or using prioritization."""
        return self.data[np.random.choice(len(self))]

    def sample_element(self) -> Trajectory:
        """Samples a single element from the buffer."""
        # Sample a trajectory.
        trajectory = self.sample_trajectory()
        state_idx = np.random.choice(len(trajectory))

        # Returns a trajectory of experiment.
        return trajectory[state_idx]

    def sample(self) -> Sequence[Trajectory]:
        """Samples a training batch."""
        batch_size = self.config.getint('train', 'batch_size')
        return [self.sample_element() for _ in range(batch_size)]


def _dump(obj, path):
    with open(path, "wb") as f:
        f.write(zlib.compress(pickle.dumps(obj, protocol=5), 1))   # ~27x smaller, ~0.3 ms
        f.flush()
        os.fsync(f.fileno())         # data is on disk before the rename makes it visible


def atomic_write(path, write_fn):
    tmp = path + ".tmp"
    write_fn(tmp)
    os.replace(tmp, path)            # the final name only ever holds a complete file


class ReplayBuffer:
    """One file per state; the newest `max_size` states form the buffer."""

    def __init__(self, config):
        self.state_ids = []
        self.state_pointer = 0
        self.buffer_dir = config.get('train', 'buffer_dir')
        self.max_size = config.getint('train', 'num_states_in_buffer')   # positions, not games
        self.discount = config.getfloat('train', 'discount')
        self.batch_size = config.getint('train', 'batch_size')
        self.export_dir = config.get('train', 'dir_name')
        self.new_samples = 0
        os.makedirs(self.buffer_dir, exist_ok=True)
        self.load()

    def __len__(self):
        return len(self.state_ids)

    def _path(self, i):
        return f"{self.buffer_dir}/s-{i}.pkl"

    def load(self):
        """Rebuild the index from disk. Safe to call after any interruption."""
        for tmp in glob(f"{self.buffer_dir}/*.tmp"):          # half-written leftovers
            os.remove(tmp)
        ids = sorted(int(os.path.basename(p)[2:-4]) for p in glob(f"{self.buffer_dir}/s-*.pkl"))
        for i in ids[:-self.max_size]:                        # evicted states
            os.remove(self._path(i))
        self.state_ids = ids[-self.max_size:]
        self.state_pointer = ids[-1] + 1 if ids else 0

    def finish_trajectory(self, seq, winner, last_reward):
        rewards = [s.reward for s in seq] + [last_reward]
        value = discounted_cumulative_sums(rewards, self.discount)[1:]
        value = np.array(value, 'float32')
        value = np.sign(value) * np.abs(value) / (np.max(np.abs(value)) + 1e-10)
        for i, (s, r) in enumerate(zip(seq, value)):
            if s.player != winner:
                r = -r
            seq[i] = s._replace(reward=r.item())
            seq[i].state_observation.action = None            # unused in training
        return seq

    def save(self, seq, winner, last_reward):
        seq = self.finish_trajectory(seq, winner, last_reward)
        for s in seq:
            atomic_write(self._path(self.state_pointer), lambda p: _dump(s, p))
            self.state_ids.append(self.state_pointer)
            self.state_pointer += 1
        excess = len(self.state_ids) - self.max_size
        if excess > 0:                                        # delete evicted files too
            for i in self.state_ids[:excess]:
                os.remove(self._path(i))
            self.state_ids = self.state_ids[excess:]
        self.new_samples += len(seq)

    def sample_element(self):
        state_id = self.state_ids[np.random.randint(len(self.state_ids))]
        with open(self._path(state_id), "rb") as f:
            return pickle.loads(zlib.decompress(f.read()))

    def sample(self):
        return [self.sample_element() for _ in range(self.batch_size)]

    def export(self):
        zip_path = self.export_dir + "replays.zip"
        with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_STORED) as z:
            for p in sorted(glob(f"{self.buffer_dir}/s-*.pkl")):
                z.write(p, arcname=os.path.basename(p))
